// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: @remotion/paths — native path drawing and evolution

const { fontFamily: interFamily } = loadInter();



export type SequenceAnimationProps = Record<string, any>;

const SequenceAnimation: React.FC<SequenceAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  lineColor = "#ffffff",
  lineWidth = 8,
  durationInSeconds = 6,
  step1Title = "1.",
  step2Title = "2.",
  step3Title = "3.",
  step1Label = "REGULATE.",
  step2Label = "REWIRE.",
  step3Label = "RISE.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Unified scale factor for typography and small details
  const s = Math.min(width, height) / 1080;

  // Responsive layout logic using width/height directly
  const boxW = width * 0.22;
  const gap = width * 0.08;
  const boxH = height * 0.28;
  const rx = 30 * s;
  const strokeW = lineWidth * s;

  // Define layout centers
  const cx2 = width / 2;
  const cx1 = cx2 - (boxW + gap);
  const cx3 = cx2 + (boxW + gap);
  const yCenter = height / 2;

  // Calculate borders. Adjusting by strokeW / 2 so the SVG path perfectly overlays the CSS border.
  const b1L = cx1 - boxW / 2 + strokeW / 2;
  const b1R = cx1 + boxW / 2 - strokeW / 2;
  const b2L = cx2 - boxW / 2 + strokeW / 2;
  const b2R = cx2 + boxW / 2 - strokeW / 2;
  const b3L = cx3 - boxW / 2 + strokeW / 2;
  const b3R = cx3 + boxW / 2 - strokeW / 2;

  const waveAmplitude = boxH * 0.35;
  const riseAmplitude = boxH * 0.45;

  // Construct the sequence path
  const pathD = `
    M 0 ${yCenter}
    L ${b2L} ${yCenter}
    C ${b2L + boxW * 0.33} ${yCenter - waveAmplitude}, ${b2L + boxW * 0.66} ${yCenter + waveAmplitude}, ${b2R} ${yCenter}
    L ${b3L} ${yCenter}
    Q ${b3L + boxW * 0.5} ${yCenter}, ${b3R} ${yCenter - riseAmplitude}
    M ${b3R} ${yCenter}
    L ${width} ${yCenter}
  `.replace(/\s+/g, " ").trim();

  // Animation timing
  const drawDuration = fps * durationInSeconds * 0.8; // line finishes before video ends
  const progress = interpolate(frame, [0, drawDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const evolution = evolvePath(progress, pathD);

  const boxes = [
    { cx: cx1, bL: b1L, title: step1Title, label: step1Label },
    { cx: cx2, bL: b2L, title: step2Title, label: step2Label },
    { cx: cx3, bL: b3L, title: step3Title, label: step3Label },
  ];

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* 1. Draw the Boxes and Text */}
      {boxes.map((box, i) => {
        // Trigger box entrance precisely when the drawing line reaches its left edge
        const startFrame = (box.bL / width) * drawDuration;
        
        const opacity = interpolate(
          frame - startFrame,
          [0, 15],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );
        
        const yOffset = interpolate(
          frame - startFrame,
          [0, 15],
          [30 * s, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: box.cx - boxW / 2,
              top: yCenter - boxH / 2,
              width: boxW,
              height: boxH,
              border: `${strokeW}px solid ${lineColor}`,
              borderRadius: rx,
              opacity,
              transform: `translateY(${yOffset}px)`,
              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              alignItems: "center",
              backgroundColor: "transparent",
              boxSizing: "border-box",
              transition: "none",
            }}
          >
            {/* Number Title */}
            <div
              style={{
                position: "absolute",
                top: -(70 * s + 15 * s),
                width: "100%",
                fontSize: 70 * s,
                lineHeight: 1,
                fontWeight: 800,
                color: lineColor,
                textAlign: "center",
              }}
            >
              {box.title}
            </div>

            {/* Label */}
            <div
              style={{
                position: "absolute",
                bottom: -(32 * s + 25 * s),
                width: "100%",
                fontSize: 32 * s,
                lineHeight: 1,
                fontWeight: 800,
                color: lineColor,
                textAlign: "center",
                textTransform: "uppercase",
                letterSpacing: 2 * s,
              }}
            >
              {box.label}
            </div>
          </div>
        );
      })}

      {/* 2. Draw the Continuous Timeline Line */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          overflow: "visible",
        }}
      >
        <path
          d={pathD}
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          fill="none"
          stroke={lineColor}
          strokeWidth={strokeW}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default SequenceAnimation;